syntax:
Namespaces are declared using the `namespace` keyword:

```c++
namespace MyNamespace {
  int myFunction(int a, int b) { return a + b; }
}

// ADL example
namespace OtherNamespace {
  int myFunction(double a, double b) { return static_cast<int>(a + b); }
}

int main() {
  int x = MyNamespace::myFunction(5, 3); // Explicit namespace qualification
  int y = myFunction(5.0, 3.0); // ADL will consider OtherNamespace due to double arguments
  return 0;
}
```
